     * Sets currently_mail_sending
     *
     * @param string|null $currently_mail_sending This is a string that can only be true or false.
     *
     * @return self
     */
    public function setCurrentlyMailSending($currently_mail_sending)
    {
        if (is_null($currently_mail_sending)) {
            throw new \InvalidArgumentException('non-nullable currently_mail_sending cannot be null');
        }
        $allowedValues = $this->getCurrentlyMailSendingAllowableValues();
        if (!in_array($currently_mail_sending, $allowedValues, true)) {
            throw new \InvalidArgumentException(
                sprintf(
                    "Invalid value '%s' for 'currently_mail_sending', must be one of '%s'",
                    $currently_mail_sending,
                    implode("', '", $allowedValues)
                )
            );
        }
        $this->container['currently_mail_sending'] = $currently_mail_sending;

        return $this;
    }

